import { VEHICLE_TYPES } from '../entities/vehicle.js';
import { scalePrice } from './difficulty.js';
import { dist } from '../util.js';

/**
 * Car dealerships. The lots themselves (building, door point, delivery bays) are generated by
 * world/city.js (`DEALER_LOTS` -> `city.locations.dealers`); what each one sells is derived from
 * `VEHICLE_TYPES[k].dealer`, so the catalogue lives in one place (entities/vehicle.js).
 */
export const DEALERS = {
  harlow: { id: 'harlow', name: 'HARLOW MOTORS', blurb: 'Everyday cars, sports cars and one very fast hypercar.' },
  ironclad: { id: 'ironclad', name: 'IRONCLAD DEPOT', blurb: 'Trucks, emergency vehicles, armour and a tank. No test drives.' },
};

/** Vehicle type keys a dealer stocks, cheapest first. */
export function stockFor(dealerId) {
  return Object.keys(VEHICLE_TYPES)
    .filter((k) => VEHICLE_TYPES[k].dealer === dealerId)
    .sort((a, b) => VEHICLE_TYPES[a].price - VEHICLE_TYPES[b].price);
}

export const mph = (ms) => Math.round(ms * 2.237);

/** What the BUY button for a type would do right now: { price, enabled, reason }. */
export function quote(game, typeKey) {
  const t = VEHICLE_TYPES[typeKey];
  const price = scalePrice(t.price, game.priceMult);
  const p = game.player;
  const dead = !p || p.dead;
  return { price, enabled: !dead && game.score >= price, reason: dead ? 'Not now' : game.score < price ? 'Not enough cash' : '' };
}

/** First delivery bay with no car in it, or null. */
function freeBay(game, bays, type) {
  for (const b of bays) {
    if (!game.vehicles.some((v) => dist(v.pos.x, v.pos.z, b.x, b.z) < (v.type.len + type.len) / 2 + 0.3)) return b;
  }
  return null;
}

/** Make room in a bay: traffic is removed (it respawns), everything else slides along the road to a free spot. */
function clearBay(game, bay, type) {
  const ax = Math.sin(bay.yaw), az = Math.cos(bay.yaw);
  for (const v of [...game.vehicles]) {
    if (dist(v.pos.x, v.pos.z, bay.x, bay.z) >= (v.type.len + type.len) / 2 + 0.3) continue;
    if (v.wrecked || (v.controller === 'npc' && !v.mission)) { game.removeVehicle(v); continue; }
    for (const d of [14, -14, 26, -26, 38, -38, 50, -50]) {
      const x = bay.x + ax * d, z = bay.z + az * d;
      if (!game.city.pointFree(x, z, 1)) continue;
      if (game.vehicles.some((o) => o !== v && dist(o.pos.x, o.pos.z, x, z) < (o.type.len + v.type.len) / 2 + 0.5)) continue;
      v.pos.set(x, 0, z); v.yaw = bay.yaw; v.vx = 0; v.vz = 0; v.speed = 0;
      v.updateMesh();
      break;
    }
    // nowhere to go (very unlikely): leave it, the physics will shove the two apart
  }
}

/**
 * Buy a vehicle from a dealer location ({ bays: [{x,z,yaw}] }). Deducts the scaled price from
 * game.score, spawns an owned car in the first free bay (pushing others aside when all are taken)
 * and returns it, or null when the purchase is not possible.
 */
export function buy(game, dealer, typeKey) {
  const t = VEHICLE_TYPES[typeKey];
  if (!t || !dealer || !dealer.bays || !dealer.bays.length) return null;
  const q = quote(game, typeKey);
  if (!q.enabled) return null;
  let bay = freeBay(game, dealer.bays, t), index = dealer.bays.indexOf(bay);
  if (!bay) { index = 0; bay = dealer.bays[0]; clearBay(game, bay, t); }
  game.score -= q.price;
  const v = game.spawnVehicle(typeKey, bay.x, bay.z, bay.yaw, { owned: true });
  v.bay = index + 1;
  game.hud.toast(`${t.name} DELIVERED - BAY ${index + 1}`);
  if (game.audio.buy) game.audio.buy(); else game.audio.cash();
  game.saveGame();
  return v;
}
